  const [current, setCurrent] = useState(getLocale());
  const [visible, setVisible] = useState(false);

  const columns = [
    { key: 'name', title: isZh ? '名称' : 'Name' },
    { key: 'age', title: isZh ? '年龄' : 'Age' },
  ];

